import data from "./marketplace.json";
import {
  CATEGORIES, SOFTWARE, TOOLS, availabilityLabel, categoryLabel, employmentLabel, isExpired, isoDate, jobValidThrough, softwareLabel, unitLabel, workplaceLabel,
} from "./marketplace-schema.mjs";
import { TEMPLATES, templateFiles } from "./templates";

// Generated by scripts/site/marketplace.mjs from marketplace/. Our own vawe templates join the gallery
// from lib/templates.ts and link to their /templates page.

export type Money = { amount: number; currency: string };
export type Creator = { handle: string; name: string; link: string; avatar?: string; bio?: string };
export type Listing = {
  id: string;
  title: string;
  summary: string;
  creator: string;
  software: string;
  version?: string;
  category: string;
  preview: string;
  poster: string;
  price: Money;
  url: string;
  tags?: string[];
  length?: number;
  resolution?: string;
  plugins?: string;
  added: string;
};
export type Pay = { min: number; max?: number; currency: string; unit: string };
export type Job = {
  id: string;
  title: string;
  company: string;
  companyUrl?: string;
  workplace: string;
  city?: string;
  countries: string[];
  employment: string[];
  pay?: Pay;
  software: string[];
  description: string;
  apply: string;
  posted: string;
};
export type Designer = {
  handle: string;
  name: string;
  link?: string;
  avatar?: string;
  reel: string;
  rate?: { amount: number; currency: string; unit: string };
  software: string[];
  availability: string;
  availableFrom?: string;
  location?: string;
  bio?: string;
  updated: string;
};

export type MarketItem = {
  key: string;
  title: string;
  summary: string;
  software: string;
  category: string;
  href: string;
  poster: string;
  preview: string;
  free: boolean;
  price: string;
  badge?: "vawe" | "vawe Pro";
  by: string;
};

export const CREATORS = data.creators as Creator[];
export const LISTINGS = data.listings as Listing[];
export const DESIGNERS = data.designers as Designer[];
const ALL_JOBS = data.jobs as Job[];

export { CATEGORIES, SOFTWARE, TOOLS, availabilityLabel, categoryLabel, employmentLabel, jobValidThrough, softwareLabel, unitLabel, workplaceLabel };

export const today = () => isoDate(new Date());
export const liveJobs = (on = today()) => ALL_JOBS.filter((j) => !isExpired(j, on)).sort((a, b) => b.posted.localeCompare(a.posted));
export const jobById = (id: string, on = today()) => liveJobs(on).find((j) => j.id === id) ?? null;

export const listingById = (id: string) => LISTINGS.find((l) => l.id === id) ?? null;
export const creatorByHandle = (handle: string) => CREATORS.find((c) => c.handle === handle) ?? null;
export const designerByHandle = (handle: string) => DESIGNERS.find((d) => d.handle === handle) ?? null;
export const listingsBy = (handle: string) => LISTINGS.filter((l) => l.creator === handle);

export const profileHandles = () => [...new Set([...CREATORS.map((c) => c.handle), ...DESIGNERS.map((d) => d.handle)])].sort();

export type Profile = { handle: string; name: string; link?: string; avatar?: string; bio?: string; designer: Designer | null; listings: Listing[] };

export function profileOf(handle: string): Profile | null {
  const creator = creatorByHandle(handle);
  const designer = designerByHandle(handle);
  if (!creator && !designer) return null;
  const base = creator ?? designer!;
  return { handle, name: base.name, link: base.link ?? designer?.link, avatar: base.avatar ?? designer?.avatar, bio: base.bio ?? designer?.bio, designer, listings: listingsBy(handle) };
}

export const money = ({ amount, currency }: Money) =>
  new Intl.NumberFormat("en", { style: "currency", currency, minimumFractionDigits: Number.isInteger(amount) ? 0 : 2 }).format(amount);

export const priceLabel = (p: Money) => (p.amount === 0 ? "Free" : money(p));

export function payLabel(p: Pay) {
  const range = p.max && p.max !== p.min ? `${money({ amount: p.min, currency: p.currency })} to ${money({ amount: p.max, currency: p.currency })}` : money({ amount: p.min, currency: p.currency });
  return `${range} ${unitLabel(p.unit)}`;
}

export const rateLabel = (r: NonNullable<Designer["rate"]>) => `${money(r)} ${unitLabel(r.unit)}`;

export function placeLabel(j: Job) {
  if (j.workplace === "remote") return `Remote, ${j.countries.join(", ")}`;
  return `${j.city}, ${j.countries[0]}${j.workplace === "hybrid" ? " (hybrid)" : ""}`;
}

export function availabilityText(d: Designer) {
  return d.availability === "soon" && d.availableFrom ? `Available from ${d.availableFrom}` : availabilityLabel(d.availability);
}

const STORES: [RegExp, string][] = [
  [/(^|\.)polar\.sh$/, "Polar"],
  [/(^|\.)gumroad\.com$/, "Gumroad"],
  [/(^|\.)lemonsqueezy\.com$/, "Lemon Squeezy"],
];

export function storeName(url: string) {
  const host = new URL(url).hostname.replace(/^www\./, "");
  return STORES.find(([re]) => re.test(host))?.[1] ?? host;
}

export const applyLabel = (apply: string) => (apply.startsWith("mailto:") ? `Apply by email` : `Apply on ${new URL(apply).hostname.replace(/^www\./, "")}`);

function vaweItems(): MarketItem[] {
  return TEMPLATES.map((t) => {
    const files = templateFiles(t);
    const pro = t.tier === "pro";
    return {
      key: `vawe-${t.id}`,
      title: t.title,
      summary: t.summary,
      software: "vawe",
      category: t.category,
      href: `/templates/${t.id}`,
      poster: files.poster,
      preview: files.mp4,
      free: !pro,
      price: pro ? "vawe Pro" : "Free",
      badge: pro ? "vawe Pro" : "vawe",
      by: "vawe",
    };
  });
}

function creatorItems(): MarketItem[] {
  return LISTINGS.map((l) => ({
    key: l.id,
    title: l.title,
    summary: l.summary,
    software: l.software,
    category: l.category,
    href: `/marketplace/${l.id}`,
    poster: l.poster,
    preview: l.preview,
    free: l.price.amount === 0,
    price: priceLabel(l.price),
    by: creatorByHandle(l.creator)?.name ?? l.creator,
  }));
}

export const marketItems = (): MarketItem[] => [...vaweItems(), ...creatorItems()];

